  function schedulesPage(){const rows=scheduleRows(),today=rows.filter(s=>s.date==='2026-10-14'),count=new Set(rows.flatMap(s=>s.persons)).size;return title('排班','按教学周安排例行事务，明确每班责任人与协作人员。',btn(I('file')+' 导出本周','export-schedules')+(canManage()?btn(I('plus')+' 新建排班','new-schedule',true):''))+summary([['本周班次',rows.length,'当前筛选'],['参与成员',count,'去重人数'],['今日班次',today.length,'10 月 14 日'],['主班已指定',rows.filter(s=>s.primary).length,'责任到人']])+`<div class="r-grid-layout"><section class="surface">${weekToolbar()}<div class="r-caption"><div class="r-key"><span><i class="r-dot"></i>例行值班</span><span><i class="r-dot archive"></i>档案 / 盖章</span><span>主 = 主班人员</span></div><span>2026–2027 学年第一学期</span><span class="r-slide-note">左右滑动查看整周</span></div><div id="r-schedule-grid">${state.mode==='week'?weekTable(rows):listTable(rows)}</div>${footer(rows.length,' 个班次')}</section><aside class="r-side"><section class="surface r-pad r-today-card"><h2>今天的安排 <small style="font-size:11px">10 / 14</small></h2>${today.length?today.map(s=>`<div class="r-agenda"><span class="r-agenda-time">${periods[s.period][1]}</span><div class="r-agenda-main"><b>${E(s.type)}</b><small>${E(s.location)}</small><small>${E(s.persons.join('、'))}</small>${link('查看班次','shift-detail',s.id)}</div></div>`).join(''):'<p>当前筛选下今天没有排班。</p>'}</section><section class="surface r-pad"><h2>排班依据</h2><ul class="r-note-list"><li><span class="r-label-icon">${I('users')}</span><div><b>成员名册</b><small>选择系统成员可关联个人排班</small></div></li><li><span class="r-label-icon">${I('calendar')}</span><div><b>核对无课周次</b><small>排班前查看对应部门无课表</small>${routeBtn('free','查看无课表')}</div></li><li><span class="r-label-icon">${I('clock')}</span><div><b>活动筹备岗位</b><small>活动草稿、发布与签到在活动排班中处理</small>${routeBtn('activity','进入活动排班')}</div></li></ul></section></aside></div>`}
