  function activityShifts(){return shifts.filter(s=>s.type==='ACTIVITY'&&s.activityId===Number(state.activityId))}
  function activityPage(){const a=activity(),all=activityShifts(),drafts=all.filter(s=>s.status==='DRAFT'),rows=all.filter(s=>state.activityStatus==='ALL'||s.status===state.activityStatus);return title('活动排班','把无课人员安排到活动各节次，复核草稿后发布并进入考勤。',canManage()?btn('人工排班','new-activity')+btn(I('spark')+' 生成排班','generate',true):'')+`<div class="r-activity-context"><div><span class="r-state blue">关联活动</span><h2>${E(a.title)}</h2><p>${E(a.department)}　${E(a.place)}　${link('查看活动详情','activity-detail',a.id)}</p></div><label><small style="display:block;margin-bottom:5px">切换活动</small><select data-r-change="activity-id">${activities.map(a=>`<option value="${a.id}" ${a.id===Number(state.activityId)?'selected':''}>${E(a.title)}</option>`).join('')}</select></label></div>`+summary([['活动班次',all.length,'当前活动'],['待发布草稿',drafts.length,'需要复核',true],['已发布',all.filter(s=>s.status==='PUBLISHED').length,'进入考勤'],['已结束',all.filter(s=>s.status==='ENDED').length,'可查看考勤']])+`<section class="surface"><div class="r-tabs" role="tablist" aria-label="活动排班视图"><button role="tab" data-r-action="activity-shifts-tab" aria-selected="${state.activityTab==='shifts'}">班次安排</button><button role="tab" data-r-action="activity-signin-tab" aria-selected="${state.activityTab==='signin'}">签到现场</button></div>${state.activityTab==='signin'?'<div class="r-pad">'+signinPanel()+'</div>':`<div class="r-process"><span data-step="1">读取无课表</span><i></i><span data-step="2" class="current">复核草稿</span><i></i><span data-step="3">发布班次</span><i></i><span data-step="4">签到与考勤</span></div><div class="r-filter">${field('班次状态',`<select data-r-change="activity-status"><option value="ALL">全部状态</option>${['DRAFT','PUBLISHED','ENDED','CANCELLED'].map(s=>`<option value="${s}" ${state.activityStatus===s?'selected':''}>${statuses[s][0]}</option>`).join('')}</select>`)}<span class="muted" style="font-size:12px">按当前活动查看，避免跨活动误操作</span><div class="r-actions">${link('查看考勤','activity-attendance')}${canManage()?btn(`发布草稿（${drafts.length}）`,'publish-all',true,`${drafts.length?'':'disabled'}`):''}</div></div>${drafts.length?`<div class="r-scope-bar"><span>${drafts.length} 个草稿班次尚未进入考勤 <small>复核人员与时段后再发布</small></span>${link('复核草稿','filter-drafts')}</div>`:''}${rows.length?`<div class="table-scroll"><table><thead><tr><th>日期 / 节次</th><th>值班人员</th><th>来源</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${s.date} <small style="display:inline">${weekdays[(new Date(s.date+'T12:00:00').getDay()+6)%7]}</small></strong><small>${shiftTime(s)} / ${periods[s.period][0]}</small></td><td>${personChips(s)}<small>${E(s.location)}</small></td><td><small>${s.source==='AUTO'?'无课表生成':'人工排班'}</small></td><td>${stateTag(s.status)}</td><td><div class="r-row-actions">${link('查看','shift-detail',s.id)}${canManage()&&s.status==='DRAFT'?link('发布','publish',s.id):''}${canManage()&&s.status==='PUBLISHED'?link('取消','cancel-shift',s.id):''}${canManage()&&s.status!=='CANCELLED'&&s.status!=='ENDED'?link('编辑','shift-edit',s.id):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('当前活动暂无匹配班次','选择其他状态，或从无课表生成活动排班。',canManage()?btn('生成排班','generate',true):'')}${footer(rows.length,' 个班次')}`}</section>`+note('生成结果按节次分别选人。周末活动请使用人工排班；发布后自动建立待签到记录。')}
  function signinPanel(){const id=Number(state.activityId),enabled=state.signin[id]===true,rs=attendance.filter(r=>shifts.find(s=>s.id===r.shiftId)?.activityId===id&&r.time);return `<div class="r-signin-grid"><section class="surface r-pad r-signin-control"><h2>活动签到码</h2>${stateTag(enabled?'PUBLISHED':'CANCELLED')}<div class="r-qr-placeholder">${I('grid')}<b>${enabled?'签到码演示占位':'签到尚未开启'}</b><small>原型不生成可扫描的签到码</small></div><p>活动统一用码 / 开启后成员扫码签到</p><div class="r-actions">${canManage()?enabled?btn('刷新演示码','refresh-signin')+btn('关闭签到','close-signin'):btn('开启签到','open-signin',true):'<span class="muted">由管理员开启签到</span>'}</div></section><section class="surface"><div class="surface-head"><h2>签到记录</h2><small>${rs.length} 位成员</small></div>${rs.length?`<div class="table-scroll"><table style="min-width:430px"><thead><tr><th>姓名</th><th>学号</th><th>签到时间</th><th>方式</th></tr></thead><tbody>${rs.map(r=>`<tr><td>${E(r.name)}</td><td>${r.studentNo}</td><td>${shifts.find(s=>s.id===r.shiftId).date.slice(5)} ${r.time}</td><td><small>${r.status==='MAKEUP'?'人工补签':'扫码签到'}</small></td></tr>`).join('')}</tbody></table></div>`:empty('还没有签到记录','开启活动签到后，成员签到记录显示在这里。')}${footer(rs.length,' 位成员')}</section></div>`}
  function attendanceRows(){return attendance.filter(r=>{const s=shifts.find(s=>s.id===r.shiftId);return s&&(state.attendanceTab!=='mine'||r.name==='林同学')&&(state.attendanceActivity==='ALL'||s.activityId===Number(state.attendanceActivity))&&(state.attendanceStatus==='ALL'||r.status===state.attendanceStatus)&&(!state.attendanceFrom||s.date>=state.attendanceFrom)&&(!state.attendanceTo||s.date<=state.attendanceTo)&&(state.attendanceType==='ALL'||activityTypeOf(s)===state.attendanceType)&&(!state.attendanceDate||s.date===state.attendanceDate)&&(`${r.name} ${r.studentNo}`).includes(state.attendanceQuery)})}
  function attendanceTable(rows){return rows.length?`<div class="table-scroll"><table><thead><tr><th>成员 / 学号</th><th>活动 / 班次</th><th>考勤结果</th><th>签到时间</th><th>来源</th><th>操作</th></tr></thead><tbody>${rows.map(r=>{const s=shifts.find(s=>s.id===r.shiftId);return `<tr><td><strong>${E(r.name)}</strong><small>${r.studentNo}</small></td><td><strong>${E(activityName(s))}</strong><small>${s.date}　${shiftTime(s)}</small></td><td>${stateTag(r.status)}</td><td>${r.time||'—'}<small>${r.signCount} 次签到</small></td><td><small>${r.source==='AUTO'?'自动判定':'人工修正'}</small></td><td><div class="r-row-actions">${link('详情','attendance-detail',r.id)}${canManage()&&state.attendanceTab!=='mine'&&r.status!=='CANCELED'?link('修正','attendance-edit',r.id):''}</div></td></tr>`}).join('')}</tbody></table></div>`:empty('没有匹配的考勤记录','调整活动、日期、人员或考勤状态后重试。',btn('重置筛选','reset-attendance'))}
  function attendancePage(){if(!canManage())state.attendanceTab='mine';const rows=attendanceRows(),count=s=>rows.filter(r=>r.status===s).length,signed=rows.filter(r=>['NORMAL','LATE','MAKEUP'].includes(r.status)).length;return title(state.attendanceTab==='mine'?'我的考勤':'考勤中心','查看排班对应的签到结果，人工修正保留原因和完整操作记录。',btn(I('file')+' 导出明细','export-attendance'))+summary([['当前记录',rows.length,'筛选范围'],['已签到',signed,'正常 / 迟到 / 补签'],['待签到',count('PENDING'),'活动结束前'],['缺勤 / 迟到',count('ABSENT')+count('LATE'),'需要核实',true]])+`<section class="surface"><div class="r-tabs" role="tablist" aria-label="考勤范围">${canManage()?`<button role="tab" data-r-action="attendance-all-tab" aria-selected="${state.attendanceTab==='all'}">考勤管理</button>`:''}<button role="tab" data-r-action="attendance-mine-tab" aria-selected="${state.attendanceTab==='mine'}">我的考勤</button></div><div class="r-filter">${field('活动',`<select data-r-change="attendance-activity"><option value="ALL">全部活动</option>${activities.map(a=>`<option value="${a.id}" ${String(a.id)===state.attendanceActivity?'selected':''}>${E(a.title)}</option>`).join('')}</select>`)}${field('班次日期',`<input type="date" data-r-change="attendance-date" value="${state.attendanceDate}">`)}<label class="r-search">姓名 / 学号<input data-r-input="attendance-search" value="${E(state.attendanceQuery)}" placeholder="输入姓名或学号"></label>${field('考勤状态',`<select data-r-change="attendance-status"><option value="ALL">全部状态</option>${['PENDING','NORMAL','LATE','ABSENT','LEAVE','EARLY_LEAVE','MAKEUP','CANCELED'].map(s=>`<option value="${s}" ${s===state.attendanceStatus?'selected':''}>${statuses[s][0]}</option>`).join('')}</select>`)}${link('重置','reset-attendance')}${link(state.attendanceAdvanced?'收起筛选':'更多筛选','attendance-advanced')}${state.attendanceAdvanced?`<div class="r-advanced-filter">${field('开始日期',`<input type="date" data-r-change="attendance-from" value="${state.attendanceFrom}">`)}${field('结束日期',`<input type="date" data-r-change="attendance-to" value="${state.attendanceTo}">`)}${field('活动类型',`<select data-r-change="attendance-type"><option value="ALL">全部活动类型</option>${Object.entries(activityTypes).map(([k,v])=>`<option value="${k}" ${state.attendanceType===k?'selected':''}>${v}</option>`).join('')}</select>`)}</div>`:''}</div><div class="r-caption"><span>正常 ${count('NORMAL')}　迟到 ${count('LATE')}　缺勤 ${count('ABSENT')}　请假 ${count('LEAVE')}　补签 ${count('MAKEUP')}　早退 ${count('EARLY_LEAVE')}　取消 ${count('CANCELED')}</span><span>摘要随筛选更新</span></div>${attendanceTable(rows)}${footer(rows.length,' 条考勤记录')}</section>`+note('活动排班发布后进入待签到；活动结束后，未签到自动判为缺勤。人工修正的记录不会被自动任务覆盖。')}
  // A deterministic, week-aware sample mirrors the imported grid's name/freeWeeks shape.
  function freeCells(day,period,dept=state.freeDept){const offset=departments.indexOf(dept)*2;return Array.from({length:3+(day+period)%3},(_,i)=>({name:people[(offset+day+period+i)%people.length],weeks:i===0?'1–20':i%2?'1–19（单）':'2–20（双）',matches:week=>i===0||Number(week)%2===(i%2?1:0)}))}
  function freeTable(dept=state.freeDept,week=state.freeWeek){return `<div class="table-scroll"><table class="r-week-table r-free-table"><thead><tr><th>节次 / 时间</th>${weekdays.slice(0,5).map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${periods.slice(0,4).map((p,pi)=>`<tr><th scope="row">${p[0]}<small>${p[1]}–${p[2]}</small></th>${weekdays.slice(0,5).map((d,di)=>`<td>${freeCells(di,pi,dept).filter(c=>week==='全部周次'||c.matches(week)).map(c=>`<div class="r-free-person"><span>${E(c.name)}</span><small>${week==='全部周次'?c.weeks:'第 '+week+' 周'}</small></div>`).join('')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
  function freePage(){const hasData=state.freeDept!=='青年科技部'&&state.freeSemester==='2026-2027-1'||state.generated&&state.freeDept===state.importDept&&state.freeSemester===state.importSemester;return title('无课表','查看部门本学期最新无课结果，按周次核对可参与人员。',canManage()?routeBtn('course','重新制作无课表'):'')+`<section class="surface"><div class="r-filter">${field('部门',`<select data-r-change="free-dept">${opt(canManage()?departments:['文秘部'],state.freeDept)}</select>`)}${field('学期',`<select data-r-change="free-semester">${opt(['2026-2027-1','2025-2026-2'],state.freeSemester)}</select>`)}${field('查看周次',`<select data-r-change="free-week"><option value="全部周次">全部周次</option>${Array.from({length:20},(_,i)=>`<option value="${i+1}" ${String(i+1)===state.freeWeek?'selected':''}>第 ${i+1} 周</option>`).join('')}</select>`)}<div class="r-actions">${link('刷新','refresh-free')}${hasData?btn('导出当前结果','export-free'):''}${canManage()&&hasData?btn('用于活动排班','free-to-activity',true):''}</div></div>${hasData?`<div class="surface-head"><div><h2>${E(state.freeDept)}无课表</h2><small>${state.freeSemester} / ${state.freeWeek==='全部周次'?'姓名后显示无课周次':'第 '+state.freeWeek+' 周可参与人员'}</small></div><span class="r-state green">最新结果</span></div><div class="r-caption"><span>最近生成：${state.generated?'本次演示生成':'2026-10-12 18:30'}</span><span>单 = 单数周 / 双 = 双数周</span></div>${freeTable()}<div class="r-table-foot"><span>节次 × 周一至周五 / 只读结果</span><span>同部门、同学期只保留最新一份</span></div>`:empty('这个部门尚未生成本学期无课表','先批量导入成员课程表，再在这里查看部门无课结果。',canManage()?btn('前往批量导入','go-import',true):'')}</section>`+note('周次表示该成员在对应节次无课的周次。自动排班使用所选活动日期对应的教学周；周末请人工安排。')}
  function courseMatrix(){return `<div class="table-scroll"><table class="r-week-table r-course-table"><thead><tr><th>节次 / 时间</th>${weekdays.map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${periods.map((p,pi)=>`<tr><th scope="row">${p[0]}<small>${p[1]}–${p[2]}</small></th>${weekdays.map((d,di)=>{const c=courses.get(`${di}-${pi}`);return `<td><button class="r-course-cell" data-r-action="course-cell" data-key="${di}-${pi}" aria-pressed="${!!c}"><b>${c?E(c):'无课'}</b>${c?'点击编辑课程':'＋ 标记有课'}</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
  function heatPeople(day,period){return state.analysisPeople.filter(n=>{if(n==='林同学')return !courseSaved.has(`${day}-${period}`);return (people.indexOf(n)+day*2+period)%4!==0})}
  function heatTable(){return `<div class="table-scroll"><table class="r-week-table r-course-table"><thead><tr><th>节次 / 时间</th>${weekdays.map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${periods.map((p,pi)=>`<tr><th>${p[0]}<small>${p[1]}–${p[2]}</small></th>${weekdays.map((d,di)=>{const n=heatPeople(di,pi).length,key=`${di}-${pi}`;return `<td><button class="r-heat ${n===state.analysisPeople.length?'':n>=state.analysisPeople.length/2?'medium':'low'} ${key===state.selectedHeat?'r-selected':''}" data-r-action="heat-cell" data-key="${key}" aria-label="${d}${p[0]}，${n}人无课"><b>${n}</b>${n===state.analysisPeople.length?'全员无课':'人无课'}</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
  function analysisPanel(){const key=state.selectedHeat||'0-2',[d,p]=key.split('-').map(Number),free=heatPeople(d,p);return `<div class="r-grid-layout"><section class="surface"><div class="r-pad"><h2>选择参与人员</h2><div class="r-toggle-people">${people.map(n=>`<label><input type="checkbox" data-r-person="${E(n)}" ${state.analysisPeople.includes(n)?'checked':''}>${E(n)}</label>`).join('')}</div>${note('使用成员保存的个人课程表分析共同空闲；不读取批量导入的周次无课表。')}</div><div class="r-filter">${field('学期',`<select data-r-change="course-semester">${opt(['2026-2027-1','2025-2026-2'],state.courseSemester)}</select>`)}${btn('分析共同空闲','analyze',true)}</div>${state.analyzed?`<div class="r-caption"><span>参与 ${state.analysisPeople.length} 人 / 点击时段查看无课人员</span><span>青绿 = 全员无课</span></div>${heatTable()}`:empty('先选择人员，再分析共同空闲','适合查找部门会议、集体工作等共同时间。')}</section><aside class="r-side"><section class="surface r-pad r-selected-slot"><h2>${state.analyzed?'所选时段':'时段详情'}</h2>${state.analyzed?`<h3>${weekdays[d]} · ${periods[p][0]}</h3><p>${periods[p][1]}–${periods[p][2]} / ${free.length} 人无课</p><div style="margin-top:14px">${free.map(n=>`<span class="r-person-chip"><span class="avatar">${n[0]}</span>${n}</span>`).join('')||'<p>此时段没有无课人员。</p>'}</div>${note(free.length===state.analysisPeople.length?'所选人员在此时段全部无课。':'其他成员在此时段有课，请选择人数更多的时段。')}`:'<p>分析后点击热力图中的时段，查看可参与成员。</p>'}</section><section class="surface r-pad"><h2>数据来源</h2><p>每位成员在“我的课程表”中保存的有课/无课标记。课程变化后，请成员更新并重新分析。</p>${routeBtn('course','查看我的课程表')}</section></aside></div>`}
  function fileRows(){return state.files.map((f,i)=>`<div class="r-file-row">${I('file')}<div class="r-file-name">${E(f.name)}<small>${f.demo?'示例课表':Math.max(1,Math.round(f.size/1024))+' KB / 未上传到服务器'}</small></div>${state.importResult?`<span class="r-state ${f.failed?'red':'green'}">${f.failed?'姓名未识别':'示例解析成功'}</span>`:''}${link('移除','remove-file',i)}</div>`).join('')}
  function importPanel(){return `<div class="r-grid-layout"><section class="surface"><div class="r-process"><span data-step="1" ${!state.importResult?'class="current"':''}>选择部门与文件</span><i></i><span data-step="2" ${state.importResult?'class="current"':''}>核对生成结果</span><i></i><span data-step="3">用于排班</span></div><div class="r-filter">${field('目标部门',`<select data-r-change="import-dept">${opt(departments,state.importDept)}</select>`)}${field('学期',`<select data-r-change="import-semester">${opt(['2026-2027-1','2025-2026-2'],state.importSemester)}</select>`)}<span class="muted" style="font-size:12px">按文件名或表内姓名识别成员</span></div><div class="r-upload">${I('file')}<h3>批量导入成员课程表</h3><p>支持 .xls、.xlsx，可一次选择多个文件</p><div class="r-actions">${btn('选择课表文件','choose-files',true)}${btn('使用示例文件','sample-files')}</div><input id="r-file-input" type="file" accept=".xls,.xlsx" multiple hidden></div><div class="r-file-list" id="r-file-list">${fileRows()}</div><div class="r-table-foot"><span>已选择 ${state.files.length} 份文件 / 仅演示导入流程</span>${btn('生成无课表','import-generate',true,state.files.length?'':'disabled')}</div></section><aside class="r-side"><section class="surface r-pad"><h2>导入前检查</h2><ul class="r-note-list"><li><div><b>文件包含姓名与课程信息</b><small>无法识别姓名时，修改文件名后重传</small></div></li><li><div><b>周次、单双周与分段课程</b><small>结果会显示每位成员的无课周次</small></div></li><li><div><b>相同部门和学期重新生成</b><small>覆盖最新无课表，请先核对目标部门</small></div></li></ul>${note('原型不解析文件内容，所有生成结果均为示例。','info')}</section></aside></div>${state.importResult?`<section class="surface r-import-result"><div class="surface-head"><div><h2>生成结果 · ${E(state.importDept)}</h2><small>${state.files.length-state.files.filter(f=>f.failed).length} 份成功 / ${state.files.filter(f=>f.failed).length} 份失败 / ${state.importSemester}</small></div><div class="r-actions">${btn('导出示例结果','export-import')}${btn('查看无课表','import-to-free',true)}</div></div>${state.files.some(f=>f.failed)?`<div class="r-pad" style="padding-top:0">${note('未识别姓名：'+state.files.filter(f=>f.failed).map(f=>E(f.name)).join('、')+'。请用成员姓名命名文件后重新选择。成功文件已生成示例结果。','warn')}</div>`:''}${freeTable(state.importDept,'全部周次')}</section>`:''}`}
  function coursePage(){if(!canManage()&&state.courseTab==='import')state.courseTab='edit';return title('无课表制作','维护个人课表，查找共同空闲，或批量制作部门无课表。')+`<div class="surface" style="margin-bottom:20px"><div class="r-tabs" role="tablist" aria-label="无课表制作方式"><button role="tab" data-r-action="course-edit-tab" aria-selected="${state.courseTab==='edit'}">我的课程表</button><button role="tab" data-r-action="course-analyze-tab" aria-selected="${state.courseTab==='analyze'}">共同空闲分析</button>${canManage()?`<button role="tab" data-r-action="course-import-tab" aria-selected="${state.courseTab==='import'}">批量导入</button>`:''}</div></div>${state.courseTab==='import'?importPanel():state.courseTab==='analyze'?analysisPanel():`<section class="surface"><div class="r-filter">${field('学期',`<select data-r-change="course-semester">${opt(['2026-2027-1','2025-2026-2'],state.courseSemester)}</select>`)}<span class="muted" style="font-size:12px">林同学 / ${courses.size} 个有课时段</span><div class="r-actions">${state.courseDirty?'<span class="r-state orange">有未保存修改</span>':'<span class="r-state green">已保存</span>'}${btn('保存课程表','save-course',true)}</div></div><div class="r-caption"><span>点击空时段添加课程；点击有课时段编辑或清除</span><span>蓝色 = 有课 / 灰色 = 无课</span></div>${courseMatrix()}<div class="r-table-foot"><span>共 ${courses.size} 个有课时段 / 个人课表不区分单双周</span>${link('分析共同空闲','course-analyze-tab')}</div></section>`}`}
  const renderers={schedules:schedulesPage,mine:minePage,activity:activityPage,attendance:attendancePage,course:coursePage,free:freePage};
  function render(){const allowed=canManage()?Object.keys(labels):['schedules','mine','activity','attendance','course','free'];if(!allowed.includes(state.page))state.page='mine';$('#r-page').innerHTML=`<nav class="r-module-nav" aria-label="排班考勤页面">${allowed.map(k=>`<button data-r-page="${k}" ${state.page===k?'aria-current="page"':''}>${labels[k]}</button>`).join('')}</nav><div class="r-page">${renderers[state.page]()}</div><p class="r-prototype-foot">V6 排班考勤设计原型 · 所有操作仅修改本页示例数据，刷新后恢复。 <a href="PAMS-UI-v6-排班考勤设计说明.md" target="_blank" rel="noopener">查看设计说明</a></p>`;$('#crumb').textContent='排班考勤 / '+labels[state.page];$$('[data-r-page]', $('.routine-subnav')).forEach(b=>{b.classList.toggle('active',b.dataset.rPage===state.page);b.setAttribute('aria-current',b.dataset.rPage===state.page?'page':'false')});$('.routine-subnav').hidden=false;$$('.nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='routine'))}
  function navigate(page,focus=true){if(!labels[page])return;state.page=page;viewNames.routine='排班考勤';showView('routine',false);render();const url=new URL(location.href);url.searchParams.set('module','routine');url.searchParams.set('page',page);history.replaceState(null,'',url);if(focus){const h=$('#r-page h1');h.tabIndex=-1;h.focus({preventScroll:true})}}
  function rerender(){render()}
  function close(){ $('#r-dialog').close() }
  function shiftDetail(id){const s=shifts.find(s=>s.id===Number(id));if(!s)return;modal('班次详情',`<div class="r-attendance-head"><h3>${E(activityName(s))}${s.type==='ACTIVITY'?stateTag(s.status):'<span class="r-state green">例行事务</span>'}</h3><p>${s.date} / ${shiftTime(s)}</p></div><dl class="r-detail-kv"><dt>值班地点</dt><dd>${E(s.location)}</dd><dt>值班人员</dt><dd>${personChips(s)}</dd><dt>班次来源</dt><dd>${s.type==='ACTIVITY'?(s.source==='AUTO'?'无课表自动生成':'人工排班'):'例行事务手动安排'}</dd><dt>工作备注</dt><dd>${E(s.note||'无备注')}</dd></dl>${s.type==='ACTIVITY'?note(s.status==='DRAFT'?'草稿尚未进入签到考勤。发布后为每位成员创建待签到记录。':s.status==='CANCELLED'?'班次已取消；人工修正过的考勤保留。':'可在活动考勤中查看本班人员的签到结果。'):note('主班负责本班事务，副班协助完成。人员变化请及时联系班次负责人。')}<div class="r-actions" style="margin-top:18px">${s.type==='ACTIVITY'?link('查看关联活动','activity-detail',s.activityId)+link('查看活动考勤','shift-attendance',s.id):''}${canManage()&&s.source==='AUTO'&&!['ENDED','CANCELLED'].includes(s.status)?link('按无课表重新生成','regenerate',s.id):''}${canManage()&&(!s.status||s.status==='DRAFT')?`<button class="link r-danger-link" data-r-action="delete-shift" data-id="${s.id}">删除班次</button>`:''}</div>`,btn('关闭','close')+(canManage()&&!['ENDED','CANCELLED'].includes(s.status)?btn('编辑班次','shift-edit',true,`data-id="${s.id}"`):''),true)}
  function personEditors(persons,primary){return persons.map(n=>`<div class="r-person-edit"><input aria-label="值班人员姓名" name="person" list="r-member-options" value="${E(n)}" placeholder="选择或输入成员"><select aria-label="主副班" name="primary"><option value="0" ${n===primary?'':'selected'}>副班</option><option value="1" ${n===primary?'selected':''}>主班</option></select><button class="icon-btn" data-r-action="remove-person" aria-label="移除此人">${I('close')}</button></div>`).join('')}
  function shiftEdit(id=null,day=2,period=0,isActivity=false){const old=shifts.find(s=>s.id===Number(id)),a=old?.type==='ACTIVITY'||isActivity,s=old||{type:a?'ACTIVITY':state.type==='全部类型'?'办公室值班':state.type,date:weekDates()[day],period,persons:['林同学','陈同学'],primary:'林同学',location:a?activity().place:'党建办公室 302',note:'',activityId:Number(state.activityId)};modal(old?'编辑班次':a?'人工创建活动排班':'新建例行排班',`<form id="r-shift-form" data-edit-id="${old?.id||''}" data-activity="${a}"><div class="r-form-grid">${a?field('关联活动',`<select name="activity">${activities.map(ac=>`<option value="${ac.id}" ${ac.id===s.activityId?'selected':''}>${E(ac.title)}</option>`).join('')}</select>`,true):field('排班类型',`<select name="type">${opt(types,s.type)}</select>`,true)}${field('排班日期',`<input name="date" type="date" value="${s.date}" required>`)}${field('对应节次',`<select name="period">${periods.slice(0,a?5:4).map((p,i)=>`<option value="${i}" ${i===s.period?'selected':''}>${p[0]}</option>`).join('')}</select>`)}${a?field('开始时间',`<input name="start" type="time" value="${s.start||periods[s.period][1]}" required>`)+field('结束时间',`<input name="end" type="time" value="${s.end||periods[s.period][2]}" required>`):''}${field('值班地点',`<input name="location" value="${E(s.location)}" required>`,true)}</div><div class="r-form-section"><h3>值班人员</h3><div id="r-person-editors">${personEditors(s.persons,s.primary)}</div>${link('＋ 添加人员','add-person')}<datalist id="r-member-options">${people.map(n=>`<option value="${E(n)}"></option>`).join('')}</datalist>${note('指定一位主班。系统成员会关联“我的排班”；手工输入的其他姓名需另行核对成员身份。')}</div>${field('工作备注',`<textarea name="note" maxlength="255" placeholder="写明值班事项或注意事项">${E(s.note||'')}</textarea>`,true)}${a&&old?.status==='PUBLISHED'?note('修改已发布班次会同步刷新人员考勤，请核对人员变动。','warn'):a?note('保存为草稿，复核后发布。'):''}<p class="r-form-error" role="alert"></p></form>`,btn('取消','close')+btn(old?'保存修改':a?'保存草稿':'保存排班','save-shift',true),true)}
  function readPeople(){const rows=$$('.r-person-edit',$('#r-dialog'));return rows.map(row=>({name:$('input',row).value.trim(),primary:$('select',row).value==='1'}))}
  function saveShift(){const f=$('#r-shift-form'),fd=new FormData(f),a=f.dataset.activity==='true',persons=readPeople();if(!f.reportValidity())return;if(!persons.length||persons.some(p=>!p.name)){dialogError('请至少安排一人，并填写每位人员的姓名。');return}if(new Set(persons.map(p=>p.name)).size!==persons.length){dialogError('同一班次不能重复安排同名人员。');return}if(persons.filter(p=>p.primary).length!==1){dialogError('请指定且仅指定一位主班人员。');return}if(a&&fd.get('start')>=fd.get('end')){dialogError('结束时间必须晚于开始时间。');return}const old=shifts.find(s=>String(s.id)===f.dataset.editId);const s={id:old?.id||nextId++,type:a?'ACTIVITY':fd.get('type'),date:fd.get('date'),period:Number(fd.get('period')),location:fd.get('location').trim(),persons:persons.map(p=>p.name),primary:persons.find(p=>p.primary).name,note:fd.get('note').trim(),...(a?{activityId:Number(fd.get('activity')),start:fd.get('start'),end:fd.get('end'),status:old?.status||'DRAFT',source:old?.source||'MANUAL'}:{})};if(old)Object.assign(old,s);else shifts.push(s);if(s.status==='PUBLISHED')syncPublished(s);close();state.page=a?'activity':'schedules';if(a)state.activityId=s.activityId;state.activityStatus='ALL';state.query='';if(!a){state.week=Math.floor((new Date(s.date+'T12:00:00Z')-new Date('2026-08-31T12:00:00Z'))/604800000)+1;state.type='全部类型'}navigate(state.page,false);toast(a&&s.status==='DRAFT'?'已保存活动排班草稿':'已保存班次')}
  function syncPublished(s){for(let i=attendance.length-1;i>=0;i--){if(attendance[i].shiftId===s.id&&!s.persons.includes(attendance[i].name)&&attendance[i].source==='AUTO')attendance.splice(i,1)}s.persons.forEach(n=>{if(!attendance.some(r=>r.shiftId===s.id&&r.name===n))attendance.push({id:nextId++,shiftId:s.id,name:n,studentNo:people.includes(n)?'20240'+String(people.indexOf(n)+1).padStart(4,'0'):'',status:'PENDING',source:'AUTO',time:'',signCount:0,audits:[]})})}
  function publish(ids){const list=shifts.filter(s=>ids.includes(s.id)&&s.status==='DRAFT');if(!list.length)return;modal('发布活动排班',`<h3>${E(activityName(list[0]))}</h3><p class="muted" style="margin-top:8px;font-size:12px">本次发布 ${list.length} 个班次，建立 ${list.reduce((n,s)=>n+s.persons.length,0)} 条待签到记录。</p><ul class="r-dialog-list">${list.map(s=>`<li><span>${s.date} ${shiftTime(s)}<small style="display:block;color:var(--muted)">${E(s.persons.join('、'))}</small></span><span>${s.persons.length} 人</span></li>`).join('')}</ul>${note('发布范围仅限下方列出的班次。发布后成员可查看安排，并进入签到考勤。','info')}`,btn('返回复核','close')+btn('确认发布','confirm-publish',true,`data-ids="${list.map(s=>s.id).join(',')}"`))}
  function generateForm(){modal('从无课表生成活动排班',`<form id="r-generate-form"><div class="r-form-grid">${field('活动方式','<select name="activityMode" data-r-form-change="activity-mode"><option value="existing">选择已有活动</option><option value="custom">自定义活动名称</option></select>',true)}<div class="full" id="r-generate-activity">${field('关联活动',`<select name="activity">${activities.map(a=>`<option value="${a.id}" ${a.id===Number(state.activityId)?'selected':''}>${E(a.title)}</option>`).join('')}</select>`)}</div>${field('开始日期','<input type="date" name="from" value="2026-10-19" required>')}${field('结束日期','<input type="date" name="to" value="2026-10-20" required>')}${field('开始时间','<input type="time" name="start" value="14:00" required>')}${field('结束时间','<input type="time" name="end" value="17:40" required>')}${field('无课表学期',`<select name="semester">${opt(['2026-2027-1','2025-2026-2'],'2026-2027-1')}</select>`)}${field('第一教学周的周一','<input type="date" name="termStart" value="2026-08-31">')}${field('每节次人数','<input type="number" name="limit" value="2" min="1" max="8" required>')}${field('参与部门',`<div class="r-toggle-people">${departments.map((d,i)=>`<label><input style="width:auto;min-height:auto" type="checkbox" name="dept" value="${d}" ${i<2?'checked':''}>${d}</label>`).join('')}</div>`,true)}</div>${note('按每个节次分别匹配无课人员，并在本次生成范围内尽量均衡安排。生成后先存草稿；无课数据缺失或周末时段不会自动排班。')}${note('填写开学日期才能过滤单双周；留空将跳过周次过滤，请人工核对。','warn')}<p class="r-form-error" role="alert"></p></form>`,btn('取消','close')+btn('生成示例草稿','generate-save',true))}
  function generateSave(){const f=$('#r-generate-form');if(!f.reportValidity())return;const fd=new FormData(f),from=fd.get('from'),to=fd.get('to'),start=fd.get('start'),end=fd.get('end'),depts=fd.getAll('dept'),limit=Number(fd.get('limit')),term=fd.get('termStart'),semester=fd.get('semester');if(from>to||start>=end){dialogError('请核对日期范围与开始、结束时间。');return}if((new Date(to)-new Date(from))/86400000>30){dialogError('演示最多生成 31 天，请缩短日期范围。');return}if(!depts.length){dialogError('请选择至少一个参与部门。');return}if(!depts.some(d=>d!=='青年科技部')&&!(state.generated&&depts.includes(state.importDept))||semester!=='2026-2027-1'&&!(state.generated&&semester===state.importSemester)){dialogError('所选部门和学期没有无课结果，请先在“无课表制作”中生成。');return}let id=Number(fd.get('activity'));if(fd.get('activityMode')==='custom'){const name=fd.get('customName')?.trim();if(!name){dialogError('请填写自定义活动名称。');return}let ac=activities.find(a=>a.title===name);if(!ac){ac={id:nextId++,title:name,department:depts.join('、'),owner:'林同学',date:from,time:start+' — '+end,place:'待确认地点',status:'策划中',done:0,total:4,materials:[]};activities.push(ac)}id=ac.id}const ac=activities.find(a=>a.id===id),usage={},created=[],skipped=[];for(let date=from;date<=to;date=dateAdd(date,1)){const di=(new Date(date+'T12:00:00Z').getUTCDay()+6)%7;if(di>4){skipped.push(date+'：周末，请人工安排');continue}const week=term?Math.floor((new Date(date+'T12:00:00Z')-new Date(term+'T12:00:00Z'))/604800000)+1:null;periods.forEach((p,pi)=>{if(p[2]<=start||p[1]>=end)return;const candidates=[...new Set(depts.filter(d=>d!=='青年科技部'||state.generated&&d===state.importDept).flatMap(d=>freeCells(di,pi,d).filter(c=>week===null||week>=1&&week<=20&&c.matches(week)).map(c=>c.name)))].sort((x,y)=>(usage[x]||0)-(usage[y]||0)||x.localeCompare(y)).slice(0,limit);if(!candidates.length){skipped.push(`${date} ${p[0]}：无可用人员`);return}candidates.forEach(n=>usage[n]=(usage[n]||0)+1);const s={id:nextId++,type:'ACTIVITY',activityId:id,date,period:pi,start:p[1],end:p[2],status:'DRAFT',source:'AUTO',persons:candidates,primary:candidates[0],location:ac.place,note:'按 '+semester+' 无课表示例生成'};shifts.push(s);created.push(s)})}state.activityId=id;state.activityStatus='DRAFT';state.activityTab='shifts';navigate('activity',false);modal('排班生成结果',`<h3>${E(ac.title)}</h3><p style="font-size:12px;margin-top:8px">已生成 ${created.length} 个草稿班次，合计 ${created.reduce((n,s)=>n+s.persons.length,0)} 人次。</p><ul class="r-dialog-list">${created.map(s=>`<li><span>${s.date} ${shiftTime(s)}</span><span>${E(s.persons.join('、'))}</span></li>`).join('')}</ul>${skipped.length?note(skipped.map(E).join('<br>'),'warn'):''}${!term?note('未填写开学日期，本次未过滤单双周，请复核人员。','warn'):''}${depts.includes('青年科技部')&&!state.generated?note('青年科技部没有无课表，该部门未参与自动选人。','warn'):''}${note('示例只验证无课周次与本次范围内分配，未进行全系统排班冲突检查。')}`,btn('查看草稿','close',true))}
  function attendanceDetail(id,edit=false){const r=attendance.find(r=>r.id===Number(id));if(!r)return;const s=shifts.find(s=>s.id===r.shiftId);modal(edit?'人工修正考勤':'考勤详情',`<div class="r-attendance-head"><h3>${E(r.name)} ${stateTag(r.status)}</h3><p>学号 ${r.studentNo||'未关联'} / ${r.source==='AUTO'?'自动判定':'人工修正'}</p></div><dl class="r-detail-kv"><dt>关联活动</dt><dd>${E(activityName(s))}</dd><dt>班次时间</dt><dd>${s.date} ${shiftTime(s)}</dd><dt>签到信息</dt><dd>${r.time||'未签到'} / ${r.signCount} 次记录</dd><dt>备注</dt><dd>${E(r.note||'无')}</dd></dl>${edit?`<form id="r-attendance-form" data-id="${r.id}" class="r-form-section">${field('修正后状态',`<select name="status">${['NORMAL','LATE','ABSENT','LEAVE','EARLY_LEAVE','MAKEUP'].map(k=>`<option value="${k}" ${k===r.status?'selected':''}>${statuses[k][0]}</option>`).join('')}</select>`)}${field('修改原因','<textarea name="reason" maxlength="255" required placeholder="填写已核实的原因，如现场漏记、因病请假"></textarea>')}${note('保存后记录操作人、时间、原状态和新状态；自动任务不再覆盖此记录。','info')}<p class="r-form-error" role="alert"></p></form>`:`${canManage()&&state.attendanceTab!=='mine'&&r.status!=='CANCELED'?`<div class="r-actions">${btn('人工修正','attendance-edit',true,`data-id="${r.id}"`)}${r.status!=='MAKEUP'?btn('补签','attendance-makeup',false,`data-id="${r.id}"`):''}</div>`:''}<div class="r-form-section"><h3>人工修改记录 <small style="color:var(--muted)">${r.audits.length} 条</small></h3>${r.audits.length?r.audits.slice().reverse().map(a=>`<div class="r-audit"><strong>${stateTag(a.old)} → ${stateTag(a.status)}</strong><p>${E(a.note)}</p><small>${a.operator} / ${a.time}</small></div>`).join(''):'<p style="color:var(--muted);font-size:12px">暂无人工修改记录，当前结果来自自动判定。</p>'}</div>`}`,edit?btn('取消','close')+btn('保存修正','save-attendance',true):btn('关闭','close'),true)}
